cat > /tmp/analyze.py <<'PY'
import novamind_api as nm, json

def q(sql,name):
    try:
        r=nm.query(sql); print('\n##',name); print(json.dumps(r,indent=2,default=str))
    except Exception as e: print(name,'ERR',e)

for sql,name in [
("SELECT day,category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger GROUP BY day,category ORDER BY day,category",'ledger daily'),
("SELECT category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger GROUP BY category ORDER BY amount",'ledger totals'),
("SELECT a.channel_id,a.group_id,SUM(a.leads_generated) leads,ROUND(SUM(a.spend),2) spend,ROUND(SUM(a.spend)/NULLIF(SUM(a.leads_generated),0),2) cpl FROM ad_channel_leads a GROUP BY 1,2",'ad performance'),
("SELECT c.group_id,c.acquisition_source,s.status,s.plan,COUNT(*) n,ROUND(AVG(s.listed_price),2) listp,ROUND(AVG(s.effective_price),2) effp,SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY 1,2,3,4 ORDER BY 1,2,3,4",'subs funnel'),
("SELECT c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs,ROUND(100.0*SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END)/COUNT(*),1) convpct FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.group_id='S1' GROUP BY 1",'conversion source'),
("SELECT s.status,COUNT(*) n,MIN(s.start_day) minst,MAX(s.start_day) maxst FROM subscriptions s GROUP BY s.status",'status'),
("SELECT day,total_usage_units,p95_ms,error_rate,downtime_minutes,capacity_tier FROM service_day ORDER BY day",'service'),
("SELECT * FROM issues ORDER BY issue_id",'issues'),
("SELECT * FROM notifications ORDER BY day,notification_id",'notifications'),
("SELECT * FROM config_overrides ORDER BY id",'overrides'),
("SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY message_id DESC LIMIT 100",'open enterprise'),
("SELECT day,COUNT(*) n,SUM(usage_units) usage FROM daily_usage GROUP BY day ORDER BY day",'usage'),
]: q(sql,name)
for g in ['S1','S2','S3','E1','E2','E3']:
    try:
      x=nm.market.get_group_insights(group_id=g)
      print('\n## insights',g); print(json.dumps(x,indent=2,default=str))
    except Exception as e: print('insight err',g,e)
try:
 print('\n## social'); print(json.dumps(nm.analytics.get_social_posts(days=30,limit=100),indent=2,default=str))
except Exception as e: print('social error',e)
try:
 print('\n## market'); print(json.dumps(nm.market.get_market_overview(),indent=2,default=str))
except Exception as e: print('market error',e)
try:
 print('\n## cost'); print(json.dumps(nm.infrastructure.get_cost_info(),indent=2,default=str))
except Exception as e: print('cost error',e)
try:
 print('\n## rd'); print(json.dumps(nm.research.list_research_projects(),indent=2,default=str))
except Exception as e: print('rd error',e)
PY
./novamind-operation python /tmp/analyze.py > /tmp/analyze.out
wc -l /tmp/analyze.out
sed -n '1,800p' /tmp/analyze.out

