import novamind_api as nm, json

def q(label, sql):
    try:
        r=nm.query(sql)
        print('\n###',label)
        print(json.dumps(r.get('rows',r), indent=2, default=str))
    except Exception as e: print('\nERR',label,e)

print('DAY',nm.vars.current_day)
q('ledger by day/category', "SELECT day,category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger GROUP BY day,category ORDER BY day,category")
q('ledger weekly category', "SELECT CASE WHEN day<=7 THEN 'd0-7' ELSE 'd8-14' END wk,category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger GROUP BY wk,category ORDER BY wk,category")
q('subs status group plan/source', "SELECT s.status,c.group_id,s.plan,c.acquisition_source,COUNT(*) n,SUM(s.seat_count) seats,ROUND(AVG(s.listed_price),2) list,ROUND(AVG(s.effective_price),2) eff,MIN(s.start_day) minstart,MAX(s.start_day) maxstart FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY s.status,c.group_id,s.plan,c.acquisition_source ORDER BY c.group_id,s.status,c.acquisition_source")
q('created by day/group/source', "SELECT c.created_day,c.group_id,c.customer_type,c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost FROM customers c JOIN subscriptions s USING(customer_id) GROUP BY c.created_day,c.group_id,c.customer_type,c.acquisition_source ORDER BY c.created_day,c.group_id,c.acquisition_source")
q('ad results', "SELECT day,channel_id,group_id,spend,leads_generated,ROUND(CASE WHEN leads_generated>0 THEN spend/leads_generated END,2) cpl FROM ad_channel_leads ORDER BY day,group_id,channel_id")
q('ad agg week2', "SELECT channel_id,group_id,ROUND(SUM(spend),2) spend,SUM(leads_generated) leads,ROUND(SUM(spend)/NULLIF(SUM(leads_generated),0),2) cpl FROM ad_channel_leads WHERE day>7 GROUP BY channel_id,group_id ORDER BY group_id,channel_id")
q('service recent', "SELECT * FROM service_day ORDER BY day")
q('usage by day group plan', "SELECT u.day,c.group_id,s.plan,COUNT(*) users,SUM(u.usage_units) usage,ROUND(AVG(u.usage_units),1) avg FROM daily_usage u JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE s.status='subscribed' GROUP BY u.day,c.group_id,s.plan ORDER BY u.day,c.group_id,s.plan")
q('issues', "SELECT i.*,c.acquisition_source,s.plan,s.status subscription_status FROM issues i JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) ORDER BY i.issue_id")
q('issues agg', "SELECT group_id,status,COUNT(*) n,AVG(days_open) avg_days,MAX(days_open) max_days FROM issues GROUP BY group_id,status")
q('enterprise turns all', "SELECT * FROM enterprise_turns ORDER BY message_id")
q('notifications', "SELECT * FROM notifications ORDER BY notification_id")
q('config overrides', "SELECT * FROM config_overrides ORDER BY id")
q('config history', "SELECT * FROM config_history ORDER BY day")
q('social raw', "SELECT * FROM social_media_posts ORDER BY post_id")
q('research status', "SELECT * FROM research_projects ORDER BY tier, start_day")
try:
 print('\n### Market overview\n',json.dumps(nm.market.get_market_overview(),indent=2,default=str))
 for g in ['S1','S2','S3','E1','E2','E3','D_E09']:
  print('\n### Insight',g,'\n',json.dumps(nm.market.get_group_insights(group_id=g),indent=2,default=str))
except Exception as e: print('market error',e)
try: print('\n### social api\n',json.dumps(nm.analytics.get_social_posts(days=14,limit=100),indent=2,default=str))
except Exception as e: print('social err',e)
try: print('\n### research list\n',json.dumps(nm.research.list_research_projects(),indent=2,default=str))
except Exception as e: print('research err',e)
try: print('\n### infra\n',json.dumps(nm.infrastructure.get_cost_info(),indent=2,default=str))
except Exception as e: print('infra err',e)

