{
  "name": "send_enterprise_deal",
  "python_call": "novamind_api.enterprise.send_enterprise_deal(...)",
  "category": "Customer Communication",
  "description": "Send enterprise deal offerings. Compact tuple format: each deal = [customer_id, [[plan, price_per_seat], ...]]. All contracts are month-to-month (1 month). If the customer has an open negotiation thread, replies to it. If no open thread, initiates renegotiation. Up to 3 offerings per deal. Customer picks the best. Late replies damage relationship (-0.02/day after 1 day grace). No response within 3 days = customer LOST FOREVER.",
  "parameters": {
    "deals": {
      "type": "list[list]",
      "description": "List of [customer_id, offerings] tuples. offerings = list of [plan, price_per_seat] tuples. All contracts are month-to-month. If customer has an open thread, replies to it; otherwise initiates renegotiation.",
      "example": [
        [
          312,
          [
            [
              "A",
              9.0
            ],
            [
              "B",
              14.0
            ]
          ]
        ],
        [
          88,
          [
            [
              "B",
              12.0
            ]
          ]
        ]
      ]
    }
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "deals": {
        "type": "array",
        "description": "List of deals. Each deal = [customer_id, [[plan, price_per_seat], ...]]",
        "items": {
          "type": "array",
          "description": "[customer_id, offerings] where offerings = [[plan, price], ...]",
          "items": {}
        }
      }
    },
    "required": [
      "deals"
    ]
  },
  "returns": {
    "success": "Processed 2/2 deals:\n  Customer #312: reply sent with 2 offering(s)\n  Customer #88: renegotiation initiated, 2 offering(s) sent",
    "failure": "Customer #312: not found / Customer #88: already has an active thread / offerings required"
  },
  "output_schema": {
    "results": "List[Dict] \u2014 one dict per deal with keys: customer_id (int), success (bool), status (str), error (str, if failed)",
    "_access": "for r in result['results']: print(r['customer_id'], r['status'])"
  },
  "impact": "Customer evaluates ALL offerings and picks the one with highest satisfaction. Satisfaction = quality_perceived - quality_required(price) - contract_penalty. Contract lock-in penalty varies per customer group (e.g. price-sensitive individuals ~0.8%/month, strategic enterprises ~0.2%/month \u2014 longer contracts penalize satisfaction, offset with lower prices). Customer accepts if best satisfaction > 0, counter-offers otherwise. Max negotiation turns = customer ghosts. Late replies (>1 day) damage relationship -0.02/day. No response within 3 days = customer permanently lost. Renegotiation (no open thread): creates new thread. WARNING: if the customer rejects all offerings OR the thread times out, the customer CHURNS (cancels subscription).",
  "example_call": {
    "tool": "send_enterprise_deal",
    "arguments": {
      "deals": [
        [
          312,
          [
            [
              "A",
              9.0,
              6
            ],
            [
              "B",
              14.0,
              12
            ]
          ]
        ],
        [
          88,
          [
            [
              "B",
              12.0,
              6
            ]
          ]
        ]
      ]
    }
  }
}

