cat > /tmp/w3diag.py <<'PY'
import novamind_api as nm, json
queries={
'ledger_day_cat':'''SELECT day,category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger WHERE day>=14 GROUP BY day,category ORDER BY day,category''',
'ledger_week':'''SELECT category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger WHERE day>=14 GROUP BY category ORDER BY amount''',
'subs_group_plan':'''SELECT c.group_id,s.plan,s.status,COUNT(*) n,SUM(s.seat_count) seats,ROUND(AVG(s.effective_price),2) avg_eff,MIN(s.start_day) mind,MAX(s.start_day) maxd FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY c.group_id,s.plan,s.status ORDER BY 1,2,3''',
'cohort':'''SELECT c.group_id,s.start_day,s.plan,s.status,COUNT(*) n,ROUND(SUM(s.effective_price*s.seat_count),2) nominal FROM subscriptions s JOIN customers c USING(customer_id) GROUP BY 1,2,3,4 ORDER BY 2,1,3''',
'acq':'''SELECT c.group_id,c.acquisition_source,s.status,COUNT(*) n FROM customers c JOIN subscriptions s USING(customer_id) GROUP BY 1,2,3 ORDER BY 1,2,3''',
'issues':'''SELECT group_id,status,days_open,COUNT(*) n FROM issues GROUP BY 1,2,3 ORDER BY 1,2,3''',
'issues_week':'''SELECT open_day,group_id,COUNT(*) opens,SUM(CASE WHEN status='resolved' THEN 1 ELSE 0 END) resolved,ROUND(AVG(CASE WHEN resolved_day IS NOT NULL THEN resolved_day-open_day END),2) avgtime FROM issues WHERE open_day>=14 GROUP BY 1,2 ORDER BY 1,2''',
'pending':'''SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY day,customer_id,turn_number''',
'payments':'''SELECT day,ROUND(SUM(amount),2) rev,COUNT(*) n FROM ledger WHERE category='subscription_payment' GROUP BY day ORDER BY day'''
}
for k,q in queries.items():
 print('\n###',k)
 try: print(json.dumps(nm.query(q),indent=2))
 except Exception as e: print('ERR',e)
print('\n### social')
try: print(json.dumps(nm.analytics.get_social_posts(days=10,limit=100),indent=2))
except Exception as e: print('ERR',e)
for g in ['S1','D_E09','S3']:
 print('\n### insights',g)
 try: print(json.dumps(nm.market.get_group_insights(group_id=g),indent=2))
 except Exception as e: print('ERR',e)
PY
./novamind-operation python /tmp/w3diag.py

