import novamind_api as nm,json
qs={
'cohort_all_groups':"SELECT s.start_day,c.group_id,s.plan,s.status,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.start_day BETWEEN 1 AND 42 GROUP BY s.start_day,c.group_id,s.plan,s.status ORDER BY s.start_day,c.group_id,s.plan,s.status",
'payments_summary':"SELECT l.day,ROUND(SUM(CASE WHEN l.amount=1 THEN l.amount ELSE 0 END),2) intro, SUM(CASE WHEN l.amount=1 THEN 1 ELSE 0 END) intro_n, ROUND(SUM(CASE WHEN l.amount>1 THEN l.amount ELSE 0 END),2) fullrev, SUM(CASE WHEN l.amount>1 THEN 1 ELSE 0 END) full_n FROM ledger l WHERE l.category='subscription_payment' AND l.day BETWEEN 31 AND 42 GROUP BY l.day ORDER BY l.day",
'issues_sub':"SELECT i.open_day,i.status,COUNT(*) n FROM issues i WHERE i.open_day BETWEEN 36 AND 42 GROUP BY i.open_day,i.status ORDER BY i.open_day,i.status",
'daily_lead_conv':"SELECT c.created_day,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) current_subs,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day BETWEEN 36 AND 42 GROUP BY c.created_day ORDER BY c.created_day",
}
for k,v in qs.items():
 print('###',k); print(json.dumps(nm.query(v)['rows'],indent=2))

import novamind_api as nm,json
qs={
'overrides':"SELECT * FROM config_overrides ORDER BY id",
'config':"SELECT * FROM config_history ORDER BY day",
'weekly_source_funnel':"SELECT CAST((c.created_day-1)/7 AS INT)+1 week,c.acquisition_source,c.group_id,COUNT(*) leads,SUM(CASE WHEN s.status IN ('subscribed','cancelled') THEN 1 ELSE 0 END) ever_subs,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) current_subs,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost FROM customers c JOIN subscriptions s USING(customer_id) GROUP BY week,c.acquisition_source,c.group_id ORDER BY week,c.group_id,c.acquisition_source",
'renewals':"SELECT s.start_day,COUNT(*) ever_subs,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) retained,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.start_day<=12 AND s.status!='lost' GROUP BY s.start_day ORDER BY s.start_day"
}
for k,v in qs.items(): print('###',k);print(json.dumps(nm.query(v)['rows'],indent=2))

