arguments.content:
"""Policy forecast: invest S1 dev until tier-1 can preserve current delivered quality."""
import novamind_api as nm
R=nm.query("SELECT start_day,plan,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY start_day,plan")['rows']
initial={(r['start_day'],r['plan']):float(r['n']) for r in R}

def sim(first=.80,repeat=.90,paid=117.4,pconv=.869,net=.0125,nconv=.875,usage=76.2,opsratio=.32,
        switchday=85,newprice=19, cash0=779834, ad=1000):
 c={(sd,p):[n,max(0,(49-sd)//30)] for (sd,p),n in initial.items()}; cash=cash0; out={}
 for day in range(50,232):
  if (day-50)%7==0:
   ns=sum(v[0] for v in c.values()); ops=max(650,opsratio*ns); u0=ns*usage
   cap=215 if u0<160000 else 530 if u0<640000 else 1330 if u0<2e6 else 4000 if u0<6.4e6 else 10000
  rev=churn=0
  for (sd,p),(n,k) in list(c.items()):
   if day>sd and (day-sd)%30==0:
    rt=first if k==0 else repeat; sv=n*rt; c[(sd,p)]=[sv,k+1]; churn+=n-sv
    pp=({'A':18,'B':79,'C':149}[p])
    if p=='A' and day>=switchday: pp=newprice
    rev+=sv*pp
  n0=sum(v[0] for v in c.values()); nl=net*n0; adds=paid*pconv+nl*nconv; c[(day,'A')]=[adds,0]; n=n0+adds
  tiercost=.0003 if day>=switchday else .002
  compute=n*usage*tiercost
  dev=500 if day<switchday else 0
  cf=adds+rev-ad-ops-dev-cap-compute-.5*(paid+nl); cash+=cf
  if day-49 in [7,28,84,182]: out[day-49]=(cash,n,adds,churn,rev,cf,ops,cap,compute,dev)
 return out
for name,kw in {
 'low':dict(first=.73,repeat=.84,paid=100,pconv=.82,net=.008,nconv=.82,usage=85,opsratio=.35,switchday=92,newprice=18),
 'base':{},
 'high':dict(first=.86,repeat=.94,paid=130,pconv=.89,net=.016,nconv=.89,usage=72,opsratio=.29,switchday=78,newprice=20),
}.items():
 o=sim(**kw); print(name,{h:{'cash':round(x[0]),'n':round(x[1]),'add':round(x[2]),'churn':round(x[3]),'rev':round(x[4]),'cf':round(x[5]),'ops':round(x[6]),'cap':x[7],'compute':round(x[8]),'dev':x[9]} for h,x in o.items()})
for first in [.72,.76,.80,.84,.88]:
 for net in [.006,.009,.012,.015,.018]:
  o=sim(first=first,repeat=min(.97,first+.1),net=net)
  print('sens',first,net,*[round(o[h][0]) for h in [7,28,84,182]],'N',*[round(o[h][1]) for h in [28,84,182]])

