q('subscription revenue daily all', "SELECT day,ROUND(SUM(amount),2) revenue,COUNT(*) bills FROM ledger WHERE category='subscription_payment' GROUP BY day ORDER BY day")
q('subscription payment detail d50-56', "SELECT day,amount,note FROM ledger WHERE category='subscription_payment' AND day BETWEEN 50 AND 56 ORDER BY day,id LIMIT 1000")
q('status cohort d1-56 aggregate', "SELECT s.start_day,s.status,COUNT(*) n,MIN(s.end_day) min_end,MAX(s.end_day) max_end FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.start_day BETWEEN 1 AND 56 GROUP BY s.start_day,s.status ORDER BY s.start_day,s.status")
q('cancellations recent by end day/start/source', "SELECT s.end_day,s.start_day,c.group_id,c.acquisition_source,COUNT(*) n FROM customers c JOIN subscriptions s USING(customer_id) WHERE s.status='cancelled' AND s.end_day BETWEEN 50 AND 56 GROUP BY s.end_day,s.start_day,c.group_id,c.acquisition_source ORDER BY s.end_day,s.start_day,c.group_id,c.acquisition_source")
q('recent lead sources', "SELECT c.created_day,c.group_id,c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day BETWEEN 50 AND 56 GROUP BY c.created_day,c.group_id,c.acquisition_source ORDER BY c.created_day,c.group_id,c.acquisition_source")
q('lead source aggregate week', "SELECT c.group_id,c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) subs,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day BETWEEN 50 AND 56 GROUP BY c.group_id,c.acquisition_source ORDER BY c.group_id,c.acquisition_source")
q('ad daily d50-56', "SELECT day,channel_id,group_id,spend,leads_generated,ROUND(spend/NULLIF(leads_generated,0),2) cpl FROM ad_channel_leads WHERE day BETWEEN 50 AND 56 ORDER BY day,group_id,channel_id")
q('ad aggregate by past weeks', "SELECT CAST((day-1)/7 AS INT)+1 week,MIN(day) first_day,MAX(day) last_day,channel_id,group_id,ROUND(SUM(spend),2) spend,SUM(leads_generated) leads,ROUND(SUM(spend)/NULLIF(SUM(leads_generated),0),2) cpl FROM ad_channel_leads GROUP BY week,channel_id,group_id ORDER BY week,group_id,channel_id")
q('service d50-56', "SELECT * FROM service_day WHERE day BETWEEN 50 AND 56 ORDER BY day")
q('open issues age', "SELECT group_id,days_open,COUNT(*) n,MIN(open_day) firstopen,MAX(open_day) lastopen FROM issues WHERE status='open' GROUP BY group_id,days_open ORDER BY group_id,days_open")
q('resolved speed recent', "SELECT open_day,COALESCE(resolved_day-open_day,-1) resolve_days,status,COUNT(*) n FROM issues WHERE open_day BETWEEN 43 AND 56 GROUP BY open_day,resolve_days,status ORDER BY open_day,resolve_days,status")
q('issue totals by day', "SELECT open_day,COUNT(*) opened,SUM(CASE WHEN status='resolved' THEN 1 ELSE 0 END) resolved,SUM(CASE WHEN status='open' THEN 1 ELSE 0 END) still_open,ROUND(AVG(CASE WHEN resolved_day IS NOT NULL THEN resolved_day-open_day END),2) avg_resolve FROM issues WHERE open_day BETWEEN 36 AND 56 GROUP BY open_day ORDER BY open_day")
q('pending enterprise customer last messages', "SELECT et.* FROM enterprise_turns et WHERE et.closed=0 AND et.message_id IN (SELECT MAX(message_id) FROM enterprise_turns WHERE closed=0 GROUP BY customer_id) ORDER BY et.day,et.message_id LIMIT 1000")
q('recent notifications', "SELECT * FROM notifications WHERE day>=49 ORDER BY day,notification_id")
q('active subs segment plan source', "SELECT c.group_id,s.plan,c.acquisition_source,COUNT(*) n,ROUND(AVG(s.effective_price),2) avgprice,ROUND(AVG(s.promotion),2) avgpromo,ROUND(AVG(s.seat_count),1) seats,MIN(s.start_day) minstart,MAX(s.start_day) maxstart FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan,c.acquisition_source ORDER BY c.group_id,s.plan,c.acquisition_source")
q('active by start week', "SELECT c.group_id,s.plan,CAST((s.start_day-1)/7 AS INT)+1 start_week,COUNT(*) n,ROUND(AVG(s.effective_price),2) price FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan,start_week ORDER BY start_week,c.group_id,s.plan")
q('current settings snapshots', "SELECT day,tool_name,setting_type,settings_json FROM config_overrides WHERE id IN (SELECT MAX(id) FROM config_overrides GROUP BY tool_name) ORDER BY tool_name")
q('config d49-56', "SELECT * FROM config_history WHERE day BETWEEN 49 AND 56 ORDER BY day")
