'subs_daily': "SELECT s.start_day day, c.group_id, COUNT(*) adds FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.start_day BETWEEN 71 AND 84 AND s.status IN ('subscribed','cancelled') GROUP BY s.start_day,c.group_id ORDER BY day,c.group_id",
'leads_daily': "SELECT arrival_day day, group_id, source, COUNT(*) leads, SUM(CASE WHEN converted_customer_id IS NOT NULL THEN 1 ELSE 0 END) conv FROM leads WHERE arrival_day BETWEEN 71 AND 84 GROUP BY arrival_day,group_id,source ORDER BY day,group_id,source",
'cancels_daily': "SELECT s.end_day day,c.group_id,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='cancelled' AND s.end_day BETWEEN 71 AND 84 GROUP BY s.end_day,c.group_id ORDER BY day,c.group_id",
'ledger_daily': "SELECT day, category, SUM(amount) amount FROM ledger WHERE day BETWEEN 71 AND 84 GROUP BY day,category ORDER BY day,category",
'issue_daily': "SELECT created_day, COUNT(*) n, SUM(CASE WHEN resolved_day IS NOT NULL THEN 1 ELSE 0 END) resolved, AVG(CASE WHEN resolved_day IS NOT NULL THEN resolved_day-created_day END) rt FROM customer_issues WHERE created_day BETWEEN 71 AND 84 GROUP BY created_day ORDER BY created_day",
