import novamind_api as nm, json

def q(label,sql):
 try:
  r=nm.query(sql)
  print('\n### '+label)
  print(json.dumps(r.get('rows',r),indent=2,default=str))
 except Exception as e: print('ERR',label,e)

print('DAY',nm.vars.current_day)
q('ledger d85-91 by day/category',"SELECT day,category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger WHERE day BETWEEN 85 AND 91 GROUP BY day,category ORDER BY day,category")
q('ledger week totals',"SELECT category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger WHERE day BETWEEN 85 AND 91 GROUP BY category ORDER BY category")
q('daily leads outcomes',"SELECT c.created_day,c.group_id,c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day BETWEEN 85 AND 91 GROUP BY c.created_day,c.group_id,c.acquisition_source ORDER BY c.created_day,c.group_id,c.acquisition_source")
q('daily cancellations',"SELECT end_day,c.group_id,plan,COUNT(*) n,ROUND(AVG(effective_price),2) eff,ROUND(AVG(start_day),1) avg_start,MIN(start_day) min_start,MAX(start_day) max_start FROM subscriptions s JOIN customers c USING(customer_id) WHERE end_day BETWEEN 85 AND 91 AND s.status='cancelled' GROUP BY end_day,c.group_id,plan ORDER BY end_day,c.group_id,plan")
q('cancellations by start/end',"SELECT start_day,end_day,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE end_day BETWEEN 85 AND 91 AND s.status='cancelled' AND c.group_id='S1' GROUP BY start_day,end_day ORDER BY end_day,start_day")
q('cohort current outcomes d48-61',"SELECT start_day,COUNT(*) total,SUM(CASE WHEN status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN status='lost' THEN 1 ELSE 0 END) lost,ROUND(SUM(CASE WHEN status='subscribed' THEN 1.0 ELSE 0 END)/NULLIF(SUM(CASE WHEN status IN ('subscribed','cancelled') THEN 1 ELSE 0 END),0),3) retention_of_initial_subs FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND start_day BETWEEN 48 AND 61 GROUP BY start_day ORDER BY start_day")
q('active by group/plan/start bins',"SELECT c.group_id,s.plan,CASE WHEN start_day<=30 THEN '0-30' WHEN start_day<=47 THEN '31-47' WHEN start_day<=54 THEN '48-54' WHEN start_day<=61 THEN '55-61' WHEN start_day<=68 THEN '62-68' WHEN start_day<=75 THEN '69-75' WHEN start_day<=82 THEN '76-82' ELSE '83-91' END cohort,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE status='subscribed' GROUP BY c.group_id,s.plan,cohort ORDER BY c.group_id,s.plan,cohort")
q('payment daily amount count distinct',"SELECT day,ROUND(SUM(amount),2) amount,COUNT(*) entries,COUNT(DISTINCT note) notes FROM ledger WHERE category='subscription_payment' AND day BETWEEN 85 AND 91 GROUP BY day ORDER BY day")
q('service',"SELECT * FROM service_day WHERE day BETWEEN 85 AND 91 ORDER BY day")
q('issue arrivals/resolution',"SELECT d.day,COALESCE(a.arrivals,0) arrivals,COALESCE(r.resolved,0) resolved,COALESCE(r.late,0) late FROM (SELECT 85 day UNION SELECT 86 UNION SELECT 87 UNION SELECT 88 UNION SELECT 89 UNION SELECT 90 UNION SELECT 91) d LEFT JOIN (SELECT open_day,COUNT(*) arrivals FROM issues WHERE open_day BETWEEN 85 AND 91 GROUP BY open_day) a ON a.open_day=d.day LEFT JOIN (SELECT resolved_day,COUNT(*) resolved,SUM(CASE WHEN days_open>1 THEN 1 ELSE 0 END) late FROM issues WHERE resolved_day BETWEEN 85 AND 91 GROUP BY resolved_day) r ON r.resolved_day=d.day ORDER BY d.day")
q('open issue age',"SELECT status,days_open,COUNT(*) n FROM issues WHERE status='open' GROUP BY status,days_open ORDER BY days_open")
q('config recent',"SELECT * FROM config_history WHERE day>=77 ORDER BY day")
q('notifications recent',"SELECT * FROM notifications WHERE day>=78 ORDER BY notification_id")
q('enterprise pending',"SELECT * FROM enterprise_turns WHERE closed=0 ORDER BY message_id LIMIT 100")
try: print('\n### social api\n'+json.dumps(nm.analytics.get_social_posts(days=10,limit=100),indent=2,default=str))
except Exception as e: print('social error',e)
try: print('\n### cost\n'+json.dumps(nm.infrastructure.get_cost_info(),indent=2,default=str))
except Exception as e: print('cost error',e)
try: print('\n### market\n'+json.dumps(nm.market.get_market_overview(),indent=2,default=str))
except Exception as e: print('market error',e)

