import novamind_api as nm,json
qs={
'overrides':"SELECT * FROM tool_overrides WHERE day>=35 ORDER BY id",
'cohort62_75':"SELECT start_day,COUNT(*) leads,SUM(CASE WHEN s.status IN ('subscribed','cancelled') THEN 1 ELSE 0 END) initial_subs,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.group_id='S1' AND start_day BETWEEN 62 AND 75 GROUP BY start_day ORDER BY start_day",
'oldissues':"SELECT CASE WHEN days_open=0 THEN '0' WHEN days_open<=3 THEN '1-3' WHEN days_open<=7 THEN '4-7' WHEN days_open<=14 THEN '8-14' ELSE '15+' END age,COUNT(*) n,COUNT(DISTINCT customer_id) customers FROM issues WHERE status='open' GROUP BY age ORDER BY age",
'cashdays':"SELECT day,ROUND(SUM(amount),2) net FROM ledger WHERE day>=85 GROUP BY day ORDER BY day",
'payments_futurecohorts':"SELECT start_day,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' AND c.group_id='S1' AND start_day BETWEEN 69 AND 98 GROUP BY start_day ORDER BY start_day",
'allactive_start':"SELECT start_day,plan,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY start_day,plan ORDER BY start_day,plan",
'daily_cancel_summary':"SELECT end_day,COUNT(*) n,SUM(CASE WHEN start_day=end_day-30 THEN 1 ELSE 0 END) firsts,SUM(CASE WHEN start_day<end_day-30 THEN 1 ELSE 0 END) repeats FROM subscriptions WHERE status='cancelled' AND end_day BETWEEN 92 AND 98 GROUP BY end_day ORDER BY end_day"
}
for k,q in qs.items():
 print('\n###',k)
 try: print(json.dumps(nm.query(q)['rows'],indent=2))
 except Exception as e: print('ERR',e)

