"""Day140 actual plan model: A1/B3 week21, S1 dev $5k/d + ops4.5k; likely repeat week22.
At d154 stop dev, B3->B2; A1 retained. Renewals can switch into B=$22 if A fails.
"""
import novamind_api as nm, math
rows=nm.query("SELECT start_day,plan,effective_price,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY start_day,plan,effective_price")['rows']
initial={(int(r['start_day']),r['plan'],float(r['effective_price'])):float(r['n']) for r in rows}

def sim(first=.50,repeat=.89,net0=.0165,netbase=.014,decay=.01,conv=.56,bshare=.97,use_a=81,use_b=84,cash0=217105,cap=1330,finalday=497,
        devdays=14,ops_high=4500,ops_after=3500,b3days=14,existing_b_switch=.85,shockgap=56,shockdays=5,shockconv=.32,shock_first=.30,shock_repeat=.76):
 c={(sd,p,pr):[n,max(0,(140-sd)//30)] for (sd,p,pr),n in initial.items()}
 cash=cash0; trace=[]; out={}
 for day in range(141,finalday+1):
  age=day-141; shock=(age%shockgap)<shockdays if shockgap<999 else False
  rev=churn=0; moves=[]
  for key,(n,k) in list(c.items()):
   sd,p,price=key
   if day>sd and (day-sd)%30==0:
    rt=((shock_first if k==0 else shock_repeat) if shock else (first if k==0 else repeat))
    sv=n*rt; churn+=n-sv; del c[key]
    # Some A survivors accept B fallback, rest remain A; existing B stays B.
    if p=='B': moves.append((sd,'B',sv,k+1))
    elif p=='C': moves.append((sd,'C',sv,k+1))
    else:
     moves.append((sd,'B',sv*existing_b_switch,k+1)); moves.append((sd,'A',sv*(1-existing_b_switch),k+1))
    rev += sv*(22*existing_b_switch+18*(1-existing_b_switch)) if p=='A' else sv*price
  for sd,p,sv,k in moves:
   if not sv: continue
   pr={'A':18.,'B':22.,'C':149.}[p]; key=(sd,p,pr)
   if key in c: c[key][0]+=sv; c[key][1]=max(c[key][1],k)
   else: c[key]=[sv,k]
  n0=sum(v[0] for v in c.values()); nett=netbase+(net0-netbase)*math.exp(-decay*age)
  leads=nett*n0*max(.15,1-n0/272812); cv=shockconv if shock else conv
  adds=leads*cv; ba=adds*bshare; aa=adds-ba
  if aa: c[(day,'A',18.)]=[aa,0]
  if ba: c[(day,'B',22.)]=[ba,0]
  ause=sum(v[0] for (sd,p,pr),v in c.items() if p=='A'); buse=sum(v[0] for (sd,p,pr),v in c.items() if p=='B'); cuse=sum(v[0] for (sd,p,pr),v in c.items() if p=='C')
  bcost=.006 if age<b3days else .002
  comp=use_a*.0003*ause+use_b*bcost*buse+60*.012*cuse
  ops=ops_high if age<devdays else ops_after; dev=5000 if age<devdays else 0
  intro=aa+ba*5; cash += intro+rev-ops-dev-cap-comp-.5*leads
  trace.append((day,cash,n0+adds,adds,churn,rev,intro,comp,leads,nett,cv,ause,buse))
  if day-140 in [7,14,28,84,182,357]: out[day-140]=trace[-1]
 return out,trace

