import novamind_api as nm
qs={
'ledger_daily':"SELECT day,category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger WHERE day BETWEEN 148 AND 154 GROUP BY day,category ORDER BY day,category",
'ledger_week':"SELECT category,ROUND(SUM(amount),2) amount,COUNT(*) n FROM ledger WHERE day BETWEEN 148 AND 154 GROUP BY category ORDER BY amount",
'active_plan':"SELECT c.group_id,s.plan,s.effective_price,COUNT(*) n,SUM(s.seat_count) seats FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' GROUP BY c.group_id,s.plan,s.effective_price ORDER BY c.group_id,s.plan,s.effective_price",
'active_start':"SELECT s.start_day,s.plan,s.effective_price,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='subscribed' AND c.customer_type='small' GROUP BY s.start_day,s.plan,s.effective_price ORDER BY s.start_day",
'new_funnel':"SELECT c.created_day,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled, SUM(CASE WHEN s.status='subscribed' AND s.plan='B' THEN 1 ELSE 0 END) active_b FROM customers c JOIN subscriptions s ON s.customer_id=c.customer_id WHERE c.customer_type='small' AND c.created_day BETWEEN 148 AND 154 GROUP BY c.created_day ORDER BY c.created_day",
'cancel_by_start':"SELECT s.start_day,s.plan,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE s.status='cancelled' AND s.end_day BETWEEN 148 AND 154 AND c.customer_type='small' GROUP BY s.start_day,s.plan ORDER BY n DESC LIMIT 50",
'issue_age':"SELECT CASE WHEN days_open=0 THEN '0' WHEN days_open<=2 THEN '1-2' WHEN days_open<=4 THEN '3-4' WHEN days_open<=7 THEN '5-7' WHEN days_open<=14 THEN '8-14' WHEN days_open<=30 THEN '15-30' ELSE '31+' END age,COUNT(*) n,MAX(days_open) mx FROM issues WHERE status='open' GROUP BY age ORDER BY MIN(days_open)",
'issue_open_daily':"SELECT open_day,COUNT(*) n FROM issues WHERE open_day BETWEEN 148 AND 154 GROUP BY open_day ORDER BY open_day",
'issue_res_daily':"SELECT resolved_day,COUNT(*) n,ROUND(AVG(days_open),2) avg_age,MAX(days_open) max_age FROM issues WHERE resolved_day BETWEEN 148 AND 154 GROUP BY resolved_day ORDER BY resolved_day",
'pending_ent':"SELECT COUNT(*) n FROM enterprise_turns WHERE closed=0",
}
for k,q in qs.items():
 print('\n###',k)
 try:
  for r in nm.query(q)['rows']: print(r)
 except Exception as e: print('ERR',e)
print('\n### social')
try: print(nm.analytics.get_social_posts(days=10,limit=50))
except Exception as e: print('ERR',e)
print('\n### cost')
try: print(nm.infrastructure.get_cost_info())
except Exception as e: print('ERR',e)
PY
