"""D154 cohort cash model after completed sprint: B2, A1, no dev/ads, ops4k."""
import novamind_api as nm, math
rows=nm.query("SELECT start_day,plan,effective_price,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY start_day,plan,effective_price")['rows']
initial={(int(r['start_day']),r['plan'],float(r['effective_price'])):float(r['n']) for r in rows}

def sim(first=.44,repeat=.95,net0=.018,netbase=.013,decay=.012,conv=.79,use_a=81,use_b=82,cash0=170349,cap=1330,finalday=497,
        ops=4000,ashare=.03,shockgap=56,shockdays=5,shockconv=.42,shock_first=.25,shock_repeat=.78,shock_dev=0):
 c={(sd,p,pr):[n,max(0,(154-sd)//30)] for (sd,p,pr),n in initial.items()}
 cash=cash0; trace=[]; out={}
 for day in range(155,finalday+1):
  age=day-155; shock=(age%shockgap)<shockdays if shockgap<999 else False
  rev=churn=0; moves=[]
  for key,(n,k) in list(c.items()):
   sd,p,price=key
   if day>sd and (day-sd)%30==0:
    rt=((shock_first if k==0 else shock_repeat) if shock else (first if k==0 else repeat))
    sv=n*rt; churn+=n-sv; del c[key]
    if p=='A':
     moves.append((sd,'B',sv*(1-ashare),k+1)); moves.append((sd,'A',sv*ashare,k+1)); rev+=sv*(22*(1-ashare)+18*ashare)
    else: moves.append((sd,p,sv,k+1)); rev+=sv*price
  for sd,p,sv,k in moves:
   if not sv: continue
   pr={'A':18.,'B':22.,'C':149.}[p]; key=(sd,p,pr)
   if key in c: c[key][0]+=sv; c[key][1]=max(c[key][1],k)
   else: c[key]=[sv,k]
  n0=sum(v[0] for v in c.values()); nett=netbase+(net0-netbase)*math.exp(-decay*age)
  leads=nett*n0*max(.15,1-n0/272812); cv=shockconv if shock else conv
  adds=leads*cv; c[(day,'B',22.)]=[adds,0]
  ause=sum(v[0] for (sd,p,pr),v in c.items() if p=='A'); buse=sum(v[0] for (sd,p,pr),v in c.items() if p=='B'); cuse=sum(v[0] for (sd,p,pr),v in c.items() if p=='C')
  comp=use_a*.0003*ause+use_b*.002*buse+50*.012*cuse
  dev=shock_dev if shock else 0
  cash += adds*5+rev-ops-dev-cap-comp-.5*leads
  trace.append((day,cash,n0+adds,adds,churn,rev,comp,leads,nett,cv,ause,buse))
  if day-154 in [7,28,84,182,343]: out[day-154]=trace[-1]
 return out,trace
scenarios={
'stress':dict(first=.28,repeat=.82,net0=.011,netbase=.0055,decay=.025,conv=.48,ashare=.12,shockgap=35,shockdays=7,shockconv=.15,shock_first=.08,shock_repeat=.55,ops=4500,shock_dev=2000),
'low':dict(first=.36,repeat=.90,net0=.014,netbase=.009,decay=.018,conv=.64,ashare=.07,shockgap=49,shockdays=5,shockconv=.28,shock_first=.15,shock_repeat=.70,ops=4200,shock_dev=1000),
'base_shock':dict(first=.44,repeat=.95,net0=.018,netbase=.013,decay=.012,conv=.79,ashare=.03,shockgap=56,shockdays=5,shockconv=.42,shock_first=.25,shock_repeat=.78,ops=4000),
'base':dict(first=.47,repeat=.96,net0=.019,netbase=.015,decay=.008,conv=.81,ashare=.02,shockgap=999,shockdays=0,ops=4000),
'high':dict(first=.57,repeat=.98,net0=.023,netbase=.019,decay=.005,conv=.87,ashare=.01,shockgap=999,shockdays=0,ops=3500),
}
for n,k in scenarios.items():
 o,t=sim(**k); mn=min(t,key=lambda x:x[1]); print(n,{h:{'cash':round(x[1]),'n':round(x[2]),'adds':round(x[3]),'churn':round(x[4]),'rev':round(x[5]),'compute':round(x[6]),'leads':round(x[7])} for h,x in o.items()},'min',round(mn[1]),mn[0],'final',round(t[-1][1]))
for sn in ['low','base_shock','base']:
 print('\n',sn,'weekly'); o,t=sim(**scenarios[sn])
 for x in t:
  if (x[0]-154)%7==0: print(*[round(y,1) if isinstance(y,float) else y for y in x])

