import novamind_api as nm, json

def q(label,sql):
 try: print('\n### '+label+'\n'+json.dumps(nm.query(sql)['rows'],indent=2,default=str))
 except Exception as e: print('ERR',label,repr(e))

print('DAY',nm.vars.current_day)
q('ledger week',"SELECT category,ROUND(SUM(amount),2) amt,COUNT(*) n FROM ledger WHERE day BETWEEN 155 AND 161 GROUP BY category ORDER BY amt")
q('daily financial',"SELECT day,ROUND(SUM(amount),2) net,ROUND(SUM(CASE WHEN category='subscription_payment' THEN amount ELSE 0 END),2) rev,ROUND(SUM(CASE WHEN category='compute' THEN amount ELSE 0 END),2) compute,ROUND(SUM(CASE WHEN category='operations' THEN amount ELSE 0 END),2) ops,ROUND(SUM(CASE WHEN category='development' THEN amount ELSE 0 END),2) dev,ROUND(SUM(CASE WHEN category='capacity' THEN amount ELSE 0 END),2) cap,ROUND(SUM(CASE WHEN category='lead_acquisition_cost' THEN amount ELSE 0 END),2) leadfee FROM ledger WHERE day BETWEEN 148 AND 161 GROUP BY day ORDER BY day")
q('daily created funnel',"SELECT c.created_day,c.group_id,c.acquisition_source,COUNT(*) leads,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) cancelled,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,ROUND(100.0*SUM(CASE WHEN s.status IN ('subscribed','cancelled') THEN 1 ELSE 0 END)/COUNT(*),1) conv FROM customers c JOIN subscriptions s USING(customer_id) WHERE c.created_day BETWEEN 148 AND 161 GROUP BY c.created_day,c.group_id,c.acquisition_source ORDER BY c.created_day,c.group_id")
q('active group plan price',"SELECT c.group_id,s.plan,s.effective_price,COUNT(*) n,SUM(s.seat_count) seats,MIN(s.start_day) minstart,MAX(s.start_day) maxstart FROM subscriptions s JOIN customers c USING(customer_id) WHERE s.status='subscribed' GROUP BY c.group_id,s.plan,s.effective_price ORDER BY c.group_id,s.plan,s.effective_price")
q('current cohort status',"SELECT s.start_day,COUNT(*) leads,SUM(CASE WHEN s.status IN ('subscribed','cancelled') THEN 1 ELSE 0 END) ever_sub,SUM(CASE WHEN s.status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN s.status='cancelled' THEN 1 ELSE 0 END) canc,SUM(CASE WHEN s.status='lost' THEN 1 ELSE 0 END) lost,SUM(CASE WHEN s.status='subscribed' AND s.plan='A' THEN 1 ELSE 0 END) a,SUM(CASE WHEN s.status='subscribed' AND s.plan='B' THEN 1 ELSE 0 END) b FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.start_day BETWEEN 110 AND 161 GROUP BY s.start_day ORDER BY s.start_day")
q('recent cancellations by age day',"SELECT end_day,end_day-start_day age,plan,effective_price,COUNT(*) n FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='S1' AND s.status='cancelled' AND end_day BETWEEN 148 AND 161 GROUP BY end_day,age,plan,effective_price ORDER BY end_day,age,plan,effective_price")
q('renewal survival cohorts',"SELECT start_day,SUM(CASE WHEN status='subscribed' THEN 1 ELSE 0 END) active,SUM(CASE WHEN status='cancelled' THEN 1 ELSE 0 END) canc,ROUND(100.0*SUM(CASE WHEN status='subscribed' THEN 1 ELSE 0 END)/COUNT(*),1) activepct FROM subscriptions WHERE start_day BETWEEN 95 AND 131 AND status IN ('subscribed','cancelled') GROUP BY start_day ORDER BY start_day")
q('daily usage',"SELECT day,COUNT(*) users,ROUND(SUM(usage_units),0) usage,ROUND(AVG(usage_units),2) avgu,MAX(usage_units) mx FROM daily_usage WHERE day BETWEEN 148 AND 161 GROUP BY day ORDER BY day")
q('usage by plan d161',"SELECT s.plan,s.effective_price,COUNT(*) n,ROUND(SUM(d.usage_units),0) usage,ROUND(AVG(d.usage_units),2) avgu,MAX(d.usage_units) mx FROM daily_usage d JOIN subscriptions s USING(customer_id) WHERE d.day=161 GROUP BY s.plan,s.effective_price ORDER BY s.plan,s.effective_price")
q('service',"SELECT * FROM service_day WHERE day BETWEEN 148 AND 161 ORDER BY day")
q('ACTIVE open issues',"SELECT SUM(CASE WHEN i.days_open=0 THEN 1 ELSE 0 END) age0,SUM(CASE WHEN i.days_open>0 THEN 1 ELSE 0 END) aged,SUM(CASE WHEN i.days_open>=4 THEN 1 ELSE 0 END) age4,SUM(CASE WHEN i.days_open>=8 THEN 1 ELSE 0 END) age8,SUM(CASE WHEN i.days_open>=15 THEN 1 ELSE 0 END) age15,MAX(i.days_open) oldest,ROUND(AVG(i.days_open),2) avg,COUNT(*) total FROM issues i JOIN subscriptions s USING(customer_id) WHERE i.status='open' AND s.status='subscribed'")
q('all open issues',"SELECT SUM(CASE WHEN days_open=0 THEN 1 ELSE 0 END) age0,SUM(CASE WHEN days_open>0 THEN 1 ELSE 0 END) aged,SUM(CASE WHEN days_open>=4 THEN 1 ELSE 0 END) age4,SUM(CASE WHEN days_open>=8 THEN 1 ELSE 0 END) age8,SUM(CASE WHEN days_open>=15 THEN 1 ELSE 0 END) age15,MAX(days_open) oldest,ROUND(AVG(days_open),2) avg,COUNT(*) total FROM issues WHERE status='open'")
q('issue opens resolutions',"SELECT d.day,(SELECT COUNT(*) FROM issues i WHERE i.open_day=d.day) opened,(SELECT COUNT(*) FROM issues i WHERE i.resolved_day=d.day) resolved FROM (SELECT DISTINCT day FROM service_day WHERE day BETWEEN 148 AND 161) d ORDER BY d.day")
