"""D161 cash model: model exact active cohorts; promo affects future B renewal price, not current effective_price."""
import novamind_api as nm, math
rows=nm.query("SELECT start_day,plan,effective_price,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY start_day,plan,effective_price")['rows']
initial={(int(r['start_day']),r['plan'],float(r['effective_price'])):float(r['n']) for r in rows}
Q0=.9287; DQ=.0225*math.log(1.6)*.75

def sim(cash0=175206,devdays=21,devspend=3000,ops=4000,cap=1330,
 lead_rate0=.0165,lead_rate_base=.013,lead_decay=.012,conv0=.64,conv_slope=1.8,
 first0=.34,first_slope=2.6,first_cap=.82,repeat=.94,
 shockgap=999,shockdays=0,shock_q=.0,shock_conv_mult=.7,shock_first_mult=.7,shock_repeat=.82,use=82,finalday=497):
 # Each bucket tracks n and renewal_count since d161. Existing active could be new/unrenewed or veteran;
 # derive tenure from start day for retention, but first future billing still gets its CURRENT effective price.
 c={(sd,p,pr):[n,max(0,(161-sd)//30),0] for (sd,p,pr),n in initial.items()}
 cash=cash0;trace=[];out={}
 for day in range(162,finalday+1):
  age=day-161;q=Q0+DQ*min(age,devdays);shock=(age%shockgap)<shockdays if shockgap<999 else False;qeff=q-(shock_q if shock else 0)
  first=max(.02,min(first_cap,first0+first_slope*(qeff-Q0)));conv=max(.15,min(.95,conv0+conv_slope*(qeff-Q0)))
  if shock:conv*=shock_conv_mult;first*=shock_first_mult
  rev=churn=0;moves=[]
  for key,(n,tenure,frenew) in list(c.items()):
   sd,p,curprice=key
   if day>sd and (day-sd)%30==0:
    rt=first if tenure==0 else (shock_repeat if shock else repeat);sv=n*rt;churn+=n-sv;del c[key]
    # Existing B currently at $22 gets charged $18 when promo first applies. New B currently at intro $1;
    # first renewal is $18. Existing A survivor is assumed to move to B18.
    newprice=18.; billprice=18.
    moves.append((sd,'B',newprice,sv,tenure+1,frenew+1));rev+=sv*billprice
  for sd,p,pr,sv,tenure,frenew in moves:
   if not sv:continue
   key=(sd,p,pr)
   if key in c:c[key][0]+=sv;c[key][1]=max(c[key][1],tenure);c[key][2]=max(c[key][2],frenew)
   else:c[key]=[sv,tenure,frenew]
  n0=sum(v[0] for v in c.values());lr=lead_rate_base+(lead_rate0-lead_rate_base)*math.exp(-lead_decay*(age-1));leads=lr*n0*max(.15,1-n0/272812);adds=leads*conv
  c[(day,'B',1.)]=[adds,0,0];rev+=adds # $17 lead promo + $4 ongoing promo gives B intro price $1
  comp=.002*use*(n0+adds);dev=devspend if age<=devdays else 0;cash+=rev-ops-dev-cap-comp-.5*leads
  row=(day,cash,n0+adds,adds,churn,rev,comp,leads,q,conv,first);trace.append(row)
  if age in [7,28,84,182,336]:out[age]=row
 return out,trace
scenarios={
'failure':dict(devdays=28,lead_rate0=.011,lead_rate_base=.0055,lead_decay=.02,conv0=.42,conv_slope=1.4,first0=.15,first_slope=1.8,first_cap=.65,repeat=.84,ops=4500,shockgap=42,shockdays=7,shock_q=.10,shock_conv_mult=.5,shock_first_mult=.5,shock_repeat=.65),
'stress':dict(devdays=28,lead_rate0=.014,lead_rate_base=.009,lead_decay=.015,conv0=.55,conv_slope=1.5,first0=.25,first_slope=2.1,first_cap=.72,repeat=.90,ops=4200,shockgap=56,shockdays=5,shock_q=.07,shock_conv_mult=.65,shock_first_mult=.65,shock_repeat=.75),
'base_shock':dict(devdays=21,lead_rate0=.0165,lead_rate_base=.013,lead_decay=.01,conv0=.64,conv_slope=1.8,first0=.34,first_slope=2.6,first_cap=.82,repeat=.94,ops=4000,shockgap=63,shockdays=5,shock_q=.055,shock_conv_mult=.7,shock_first_mult=.7,shock_repeat=.80),
'base':dict(devdays=21,lead_rate0=.017,lead_rate_base=.014,lead_decay=.008,conv0=.66,conv_slope=1.9,first0=.38,first_slope=2.7,first_cap=.85,repeat=.95,ops=4000),
'high':dict(devdays=14,lead_rate0=.020,lead_rate_base=.017,lead_decay=.005,conv0=.72,conv_slope=2.0,first0=.48,first_slope=2.8,first_cap=.90,repeat=.97,ops=3500)}
for name,kw in scenarios.items():
 o,t=sim(**kw);mn=min(t,key=lambda x:x[1]);print(name,{h:{'cash':round(x[1]),'n':round(x[2]),'adds':round(x[3]),'churn':round(x[4]),'rev':round(x[5]),'comp':round(x[6]),'leads':round(x[7]),'q':round(x[8],3),'conv':round(x[9],2),'first':round(x[10],2)} for h,x in o.items()},'min',round(mn[1]),mn[0],'final',round(t[-1][1]))
for name in ['stress','base_shock','base']:
 print('\n'+name+' weekly');o,t=sim(**scenarios[name])
 for x in t:
  if (x[0]-161)%7==0:print(*[round(y,2) if isinstance(y,float) else y for y in x])

