"""D168 scenario model after B3, $18 list price, no lead promo/dev/ads, ops4k."""
import novamind_api as nm,math
rows=nm.query("SELECT start_day,plan,effective_price,COUNT(*) n FROM subscriptions WHERE status='subscribed' GROUP BY start_day,plan,effective_price")['rows']
initial={(int(r['start_day']),r['plan'],float(r['effective_price'])):float(r['n']) for r in rows}

# Segment current book: first future evaluation survival depends on acquisition cohort.
# d139+ unrenewed, d120-124 survived one very poor cycle but may stabilize; all earlier veteran.
def sim(cash0=112503,ops=4000,cap=1330,lead_rate0=.017,lead_rate_base=.014,lead_decay=.008,
        conv=.72,first_recent=.65,first_early=.88,repeat=.95,use=82,shockgap=70,shockdays=4,
        shock_conv=.70,shock_first=.75,shock_repeat=.85,finalday=497):
 c={k:[n,max(0,(168-k[0])//30)] for k,n in initial.items()};cash=cash0;trace=[];out={}
 for day in range(169,finalday+1):
  age=day-168;shock=(age%shockgap)<shockdays if shockgap<999 else False;rev=churn=0;moves=[]
  for key,(n,tenure) in list(c.items()):
   sd,p,pr=key
   if day>sd and (day-sd)%30==0:
    if tenure==0:rt=first_recent
    elif sd>=120:rt=first_early
    else:rt=repeat
    if shock:rt*=shock_first if tenure==0 else shock_repeat
    sv=n*rt;churn+=n-sv;del c[key];moves.append((sd,'B',18.,sv,tenure+1));rev+=18*sv
  for sd,p,pr,n,tenure in moves:
   key=(sd,p,pr)
   if key in c:c[key][0]+=n;c[key][1]=max(c[key][1],tenure)
   else:c[key]=[n,tenure]
  n0=sum(x[0] for x in c.values());lr=lead_rate_base+(lead_rate0-lead_rate_base)*math.exp(-lead_decay*(age-1));leads=lr*n0*max(.15,1-n0/272812);cv=conv*(shock_conv if shock else 1);adds=leads*cv
  c[(day,'B',18.)]=[adds,0];rev+=18*adds
  # B3 dominates. Tiny A/C legacy omitted from compute nuance; use observed mean.
  comp=.006*use*(n0+adds);cash+=rev-ops-cap-comp-.5*leads
  x=(day,cash,n0+adds,adds,churn,rev,comp,leads,cv);trace.append(x)
  if age in [7,28,84,182,329]:out[age]=x
 return out,trace
