cat > /tmp/w26sat.py <<'PY'
import novamind_api as nm,json
qs={
'cancel_day':'''SELECT end_day,COUNT(*) n FROM subscriptions WHERE end_day>=139 GROUP BY end_day ORDER BY end_day''',
'survival_start':'''SELECT start_day, COUNT(*) ever, SUM(CASE WHEN status='subscribed' THEN 1 ELSE 0 END) active, ROUND(100.0*SUM(CASE WHEN status='subscribed' THEN 1 ELSE 0 END)/COUNT(*),1) pct FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id='S1' AND start_day BETWEEN 120 AND 152 AND status IN ('subscribed','cancelled') GROUP BY start_day ORDER BY start_day''',
'renewers_week':'''SELECT s.start_day,s.status,s.listed_price,s.promotion,s.effective_price,COUNT(*) n FROM subscriptions s JOIN customers c ON c.customer_id=s.customer_id WHERE c.group_id='S1' AND s.start_day BETWEEN 146 AND 152 GROUP BY s.start_day,s.status,s.listed_price,s.promotion,s.effective_price ORDER BY s.start_day,s.status'''
}
for k,q in qs.items():print('\n#'+k+'\n'+json.dumps(nm.query(q)['rows'],indent=2))
PY
./novamind-operation python /tmp/w26sat.py

